    /** Scandals, leaks, investigations, pardons and impeachment. */
    static final class Trouble {
        public static Scandal add(Game g, int kind, String title, String body, double sev, Person who, boolean impeachable) {
            Scandal s = new Scandal();
            s.kind = kind; s.title = title; s.body = body; s.severity = sev; s.person = who; s.who = who != null ? who.name : null;
            s.started = g.week; s.impeachable = impeachable;
            g.ex.scandals.add(s);
            g.scandal += sev * 0.35;
            if (sev >= 3) {
                g.log(NK_BIG, title.toUpperCase(), body, 1.5 + sev * 0.4);
                respond(g, s);
            } else g.log(NK_BAD, title, body, 0.8 + sev * 0.3);
            return s;
        }

        /** Asks how to handle a serious story. */
        static void respond(Game g, Scandal s) {
            List<String> o = new ArrayList<String>(), adv = new ArrayList<String>();
            List<Integer> codes = new ArrayList<Integer>();
            o.add("Release everything and get ahead of it"); adv.add("Communications director: \"Take the hit now and it's a one-week story.\""); codes.add(0);
            o.add("Deny it and attack the coverage"); adv.add("Political director: \"Our voters don't trust these outlets anyway.\""); codes.add(1);
            if (s.person != null && (Cabinet.everyone(g).contains(s.person))) { o.add("Ask " + s.person.name + " to resign"); adv.add("Chief of staff: \"Cut it off before it reaches you.\""); codes.add(2); }
            o.add("Order an independent review"); adv.add("Counsel: \"Let someone credible look at it. It buys time and it looks serious.\""); codes.add(3);
            String[] oa = o.toArray(new String[0]), aa = adv.toArray(new String[0]);
            Decision d = Decisions.add(g, D_SCANDAL, s.title, s.body + " About " + Math.round(20 + s.severity * 6) + "% of Americans say they've heard a lot about it.", oa, aa);
            d.scandalRef = s;
            d.codes = new int[codes.size()];
            for (int i = 0; i < d.codes.length; i++) d.codes[i] = codes.get(i);
        }

        public static void scandalDecision(Game g, Scandal s, int code) {
            Random r = g.rng;
            s.answered = true;
            if (code == 0) { s.severity = Math.max(0.5, s.severity - 1.2); g.perf -= 0.3; g.log(NK_INFO, "The White House releases documents on " + s.title.toLowerCase(), null, 0.9); }
            else if (code == 1) {
                for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 1);
                if (r.nextDouble() < 0.35 + s.severity * 0.04) { s.severity += 2; g.log(NK_BAD, "New reporting contradicts the White House on " + s.title.toLowerCase(), null, 1.8); }
            } else if (code == 2 && s.person != null) {
                Cabinet.remove(g, s.person);
                g.ex.departures++;
                s.severity = Math.max(0.5, s.severity - 2.2);
                for (Person p : Cabinet.everyone(g)) p.morale = Math.max(0, p.morale - 2);
                g.log(NK_BAD, s.person.name + " resigns as " + lcTitle(s.person.title()), null, 1.6);
            } else if (code == 3) { s.stage = Math.max(s.stage, 1); s.severity *= 0.9; g.log(NK_INFO, "An independent review of " + s.title.toLowerCase() + " begins", null, 0.9); }
        }

        static void leak(Game g, Person p) {
            Exec x = g.ex;
            x.leaks++;
            String[] about = {"shouting matches over " + PISSUE[Week.topIssue(g)].toLowerCase(), "the president's temper and long days", "infighting between the chief of staff and the cabinet",
                    "second thoughts about the administration's agenda", "who's up and who's down in the West Wing"};
            String what = about[g.rng.nextInt(about.length)];
            if (g.stamina < 30) what = "how tired the president looks after long days";
            String src = p.real ? "unnamed aides" : p.trait == T_LEAKER || p.morale < 35 ? "aides close to " + p.name : "unnamed aides";
            Scandal s = add(g, SK_LEAK, "Leak: West Wing aides describe " + what, "The story quotes " + src + ".", 1 + g.rng.nextDouble() * 1.2, p.real ? null : p, false);
            if (s.severity < 3 && g.rng.nextDouble() < 0.5) {
                Decision d = Decisions.add(g, D_LEAK, "Another leak", "The Capital Ledger is running a story built on " + src + ". It describes " + what + ".",
                        new String[]{"Hunt for the leaker", "Ignore it", "Tell the staff: one more leak and people go"},
                        new String[]{"Counsel: \"A leak investigation sends a message.\"", "Chief of staff: \"Every White House leaks. Don't feed it.\"", "Press secretary: \"Say it once, in the staff meeting, and mean it.\""});
                d.person = p.real ? null : p;
            }
        }

        public static void leakDecision(Game g, Person p, int k) {
            Exec x = g.ex;
            if (k == 0) {
                for (Person o : Cabinet.everyone(g)) o.morale = Math.max(0, o.morale - 4);
                if (p != null && g.rng.nextDouble() < 0.45) { Cabinet.remove(g, p); x.departures++; g.log(NK_BAD, p.name + " is pushed out after a leak investigation", null, 1.4); }
                else g.log(NK_INFO, "A White House leak investigation turns up nothing", null, 0.7);
            } else if (k == 2) {
                for (Person o : Cabinet.everyone(g)) { o.morale = Math.max(0, o.morale - 2); o.loyalty = Math.min(100, o.loyalty + 2); }
            }
        }

        static void ethics(Game g, Person p) {
            String[] what = {"billed taxpayers for first-class travel and a $40,000 office renovation", "met with lobbyists for a former client while writing rules that affect it",
                    "used government staff to run personal errands", "kept trading stocks in industries the department regulates", "steered a contract to a friend's company"};
            add(g, SK_ETHICS, p.title() + " " + p.name + " under fire", "Reporters say " + p.name + " " + what[g.rng.nextInt(what.length)] + ".", 2.5 + g.rng.nextDouble() * 2.5, p, false);
        }

        public static void week(Game g) {
            Exec x = g.ex;
            Random r = g.rng;
            double press = Cabinet.sq(g, S_PRESS);
            // scandals fade, or grow
            for (Scandal s : x.scandals) {
                if (s.over) continue;
                boolean probed = false;
                for (Probe p : x.probes) if (!p.over && p.scandal == s) probed = true;
                double decay = probed ? 0.995 : s.stage == 1 ? 0.965 : 0.975 - 0.02 * press;
                s.severity *= decay;
                if (r.nextDouble() < 0.012 * s.severity * (1.2 - Cabinet.sq(g, S_COUNSEL) * 0.5) && s.kind != SK_LEAK) {
                    s.severity += 1 + r.nextDouble();
                    g.log(NK_BAD, "New revelations in " + s.title.toLowerCase(), null, 1.2 + s.severity * 0.2);
                }
                g.scandal += 0.009 * s.severity;
                if (s.severity >= 7 && s.stage < 2 && s.impeachable && x.post[P_DOJ] != null && x.post[P_DOJ].loyalty < 85 && r.nextDouble() < 0.06) {
                    s.stage = 2;
                    g.log(NK_BIG, "ATTORNEY GENERAL APPOINTS A SPECIAL COUNSEL TO INVESTIGATE " + s.title.toUpperCase(), null, 4);
                }
                if (s.severity < 0.6) s.over = true;
            }
            // something from the president's own past
            Cand p = g.pres;
            if (p != null && r.nextDouble() < 0.0006 + p.a[A_SCA] / 60000.0) {
                String[] past = {"Old business deals with a foreign investor resurface", "A former employee sues over the president's past business", "Questions about the president's taxes return", "A book by a former aide paints an unflattering picture"};
                add(g, SK_PAST, past[r.nextInt(past.length)], "The White House calls it old news.", 2 + r.nextDouble() * 2.5, null, false);
            }
            // pardon requests
            if (g.week >= x.nextPardon) { pardon(g); x.nextPardon = g.week + 8 + r.nextInt(8); }
            // oversight
            boolean oppH = !Hill.majority(g, HOUSE, g.party), oppS = !Hill.majority(g, SENATE, g.party);
            if ((oppH || oppS) && g.week >= x.nextProbe) { probe(g, oppH ? HOUSE : SENATE); x.nextProbe = g.week + 10 + r.nextInt(9); }
            for (Probe pr : x.probes) if (!pr.over && g.week >= pr.until) endProbe(g, pr);
            impeachment(g);
            // the vice president and the delegates
            VicePres.week(g);
            if (x.deleg[DG_WHIP]) Decisions.autoWhip(g);
        }

        // ---- pardons ----
        static void pardon(Game g) {
            Random r = g.rng;
            int i = r.nextInt(PARDONS.length);
            if (g.tw() < 30 && i == 1) i = 0;
            String[] t = PARDONS[i].split("\\|");
            int kind = Integer.parseInt(t[2]);
            Decision d = Decisions.add(g, D_PARDON, "A request for clemency: " + t[0].toLowerCase(), t[1] + " The pardon attorney's file is on your desk.",
                    new String[]{"Grant a full pardon", "Deny it", "Commute the sentence instead"},
                    new String[]{kind == 1 || kind == 5 ? "Political director: \"Our people have been asking for this.\"" : "Counsel: \"The case for mercy is strong.\"",
                            "Counsel: \"There's no reason to take the risk.\"", "Chief of staff: \"Split the difference: let them out, don't wipe the slate.\""});
            d.a = kind; d.b = i;
            if (g.ex.deleg[DG_PARDONS]) { g.inbox.remove(d); pardonDecision(g, d, kind == 0 || kind == 6 ? 0 : kind == 3 ? 2 : 1); g.log(NK_INFO, "Your counsel handles a clemency request", null, 0.3); }
        }

        public static void pardonDecision(Game g, Decision d, int k) {
            if (k == 1) return;
            int kind = d.a;
            double m = k == 2 ? 0.5 : 1;
            Exec x = g.ex;
            x.pardons++;
            String who = PARDONS[d.b].split("\\|")[0].toLowerCase();
            g.log(kind == 1 || kind == 2 ? NK_BIG : NK_INFO, (k == 2 ? "President " + g.pres.last + " commutes the sentence of " : "President " + g.pres.last + " pardons ") + who, null, kind == 1 || kind == 2 ? 2.4 : 1.0);
            switch (kind) {
                case 0: groupBump(g, 10, 1.2 * m); g.perf += 0.1; break;
                case 1: for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 2); add(g, SK_PARDON, "The pardon of " + who, "Critics call it a reward for loyalty and a warning to investigators.", 4.5 * m, null, true); break;
                case 2: add(g, SK_PARDON, "The pardon of " + who, "Records show the donor's family gave to the president's allies after the request was filed.", 5.5 * m, null, true); g.issueAdj[PI_ETHICS] -= 0.3 * m; break;
                case 3: groupBump(g, 25, 1 * m); g.perf -= 0.2 * m; g.issueAdj[PI_SECURITY] += g.party == REP ? 0.05 : -0.1; break;
                case 4: groupBump(g, 0, 1 * m); g.issueAdj[PI_SECURITY] -= 0.2 * m; if (x.post[P_CIA] != null) x.post[P_CIA].morale -= 10; if (x.post[P_DNI] != null) x.post[P_DNI].morale -= 8; break;
                case 5: for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 1.5); add(g, SK_PARDON, "Pardons for the rioters", "Police unions and the other party condemn them.", 3 * m, null, false); g.issueAdj[PI_CRIME] -= 0.3 * m; break;
                default: groupBump(g, 10, 0.4 * m); g.perf += 0.05; break;
            }
        }

        // ---- oversight ----
        static void probe(Game g, int chamber) {
            Exec x = g.ex;
            Probe p = new Probe();
            p.chamber = chamber; p.started = g.week; p.until = g.week + 10;
            Scandal target = null;
            for (Scandal s : x.scandals) if (!s.over && s.kind != SK_LEAK && (target == null || s.severity > target.severity)) target = s;
            boolean taken = false;
            for (Probe o : x.probes) if (!o.over && o.scandal == target) taken = true;
            if (target != null && !taken) { p.scandal = target; p.topic = target.title.toLowerCase(); target.stage = Math.max(target.stage, 1); }
            else {
                Action hot = null;
                for (Action a : x.actions) if (a.status == A_LIVE && a.lean == g.party && (hot == null || a.support < hot.support)) hot = a;
                p.topic = hot != null ? hot.name.toLowerCase() : x.failures > 0 ? "problems at " + POST_NAME[worstPost(g)] : "the administration's spending";
                p.scandal = add(g, SK_POWER, "Congress investigates " + p.topic, "The committee wants documents and testimony from senior officials.", 1.6, null, false);
            }
            Member chair = null;
            for (Member m : g.cong.members) if (m.role == RO_CHAIR && m.chamber == chamber && m.party != g.party && (m.committee.contains("Oversight") || m.committee.contains("Judiciary") || m.committee.contains("Homeland") || m.committee.contains("Govern") || m.committee.contains("Expenditures"))) { chair = m; break; }
            p.chair = chair != null ? chair.name : "The committee chair";
            x.probes.add(p);
            g.log(NK_BAD, p.chair + " opens an investigation into " + p.topic, null, 1.6);
            Decision d = Decisions.add(g, D_SUBPOENA, "A subpoena from Congress", p.chair + " has subpoenaed White House documents and testimony from senior aides about " + p.topic + ".",
                    new String[]{"Comply and hand them over", "Negotiate a narrower request", "Claim executive privilege", "Refuse to cooperate"},
                    new String[]{"Counsel: \"There's nothing in there we can't explain.\"", "Legislative director: \"Give them enough to say they won.\"", "Counsel: \"Privilege protects the office, not just you. The courts will take months.\"",
                            "Political director: \"It's a fishing expedition. Our voters will back us.\""});
            d.probeRef = p;
        }

        static int worstPost(Game g) { int w = 0; for (int k = 1; k < NPOST; k++) if (postOn(k) && g.ex.ready[k] < g.ex.ready[w]) w = k; return w; }

        public static void subpoenaDecision(Game g, Probe p, int k) {
            Exec x = g.ex;
            Random r = g.rng;
            p.response = k;
            Scandal s = p.scandal;
            double cq = Cabinet.sq(g, S_COUNSEL);
            if (k == 0) { if (s != null) s.severity += r.nextDouble() * 2 - 0.6; p.until = g.week + 8; }
            else if (k == 1) {
                if (r.nextDouble() < 0.35 + 0.5 * cq) { if (s != null) s.severity += r.nextDouble() - 0.6; p.until = g.week + 7; g.log(NK_INFO, "The White House and " + p.chair + " reach a deal on documents", null, 0.8); }
                else { if (s != null) s.severity += 1; p.until = g.week + 10; g.log(NK_BAD, p.chair + " rejects the White House's offer and threatens contempt", null, 1.2); }
            } else if (k == 2) { p.privilegeCase = true; p.until = g.week + 14 + r.nextInt(10); g.log(NK_INFO, "The White House claims executive privilege; the fight goes to court", null, 1.4); }
            else {
                x.contempt++;
                if (s != null) { s.severity += 2; s.impeachable = true; }
                g.perf -= 0.5;
                for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 1);
                g.log(NK_BIG, (CHAMBER[p.chamber] + " votes to hold White House officials in contempt of Congress").toUpperCase(), null, 2.8);
                p.until = g.week + 12;
            }
        }

        static void endProbe(Game g, Probe p) {
            p.over = true;
            Scandal s = p.scandal;
            if (p.privilegeCase) {
                boolean win = g.rng.nextDouble() < 0.35 + 0.3 * Cabinet.sq(g, S_COUNSEL);
                if (win) { if (s != null) s.severity *= 0.6; g.log(NK_GOOD, "A judge upholds the White House's claim of executive privilege", null, 1.6); }
                else { if (s != null) s.severity += 1.5; g.log(NK_BAD, "Courts reject the White House's privilege claim; the documents go to Congress", null, 2.0); }
                return;
            }
            String verdict = s == null || s.severity < 2.5 ? "finds poor judgment but no wrongdoing" : s.severity < 5 ? "accuses the administration of misleading Congress" : "says senior officials may have broken the law";
            g.log(s != null && s.severity >= 5 ? NK_BIG : NK_BAD, "The " + CHAMBER[p.chamber] + " report on " + p.topic + " " + verdict, null, s != null && s.severity >= 5 ? 3 : 1.4);
            if (s != null && s.severity >= 5) s.impeachable = true;
        }

        // ---- impeachment ----
        static void impeachment(Game g) {
            Exec x = g.ex;
            Random r = g.rng;
            double pr = 2 * x.contempt + 3 * x.defiance;
            for (Scandal s : x.scandals) if (!s.over && s.impeachable) pr += s.severity;
            x.impPressure = pr;
            boolean oppH = !Hill.majority(g, HOUSE, g.party);
            if (x.impStage == 0 && oppH && pr >= 9 && r.nextDouble() < 0.06 + (pr - 9) * 0.01) {
                x.impStage = 1; x.impWeek = g.week + 8 + r.nextInt(6);
                g.log(NK_BIG, "THE HOUSE OPENS AN IMPEACHMENT INQUIRY", "The Judiciary Committee will decide whether to draft articles of impeachment.", 4.5);
                Decisions.add(g, D_IMPEACH, "An impeachment inquiry", "The House has opened an impeachment inquiry. Hearings start within weeks. How do you respond?",
                        new String[]{"Cooperate and make your case", "Stonewall: no witnesses, no documents", "Take it to the country: rallies and prime-time speeches"},
                        new String[]{"Counsel: \"If we have nothing to hide, show it.\"", "Political director: \"It's a partisan show. Don't dignify it.\"", "Communications director: \"Make it a referendum on them.\""});
                return;
            }
            if (x.impStage == 1 && g.week >= x.impWeek) {
                int yes = 0;
                for (Bloc b : g.cong.blocs) {
                    if (b.chamber != HOUSE) continue;
                    double p = b.party == g.party ? logistic(-4.5 + 0.18 * pr + (40 - g.approval) * 0.05) : logistic(-1.2 + 0.28 * pr - (b.name.contains("Blue Dogs") || b.name.contains("Problem") ? 0.8 : 0));
                    for (int i = 0; i < b.seats; i++) if (r.nextDouble() < p) yes++;
                }
                if (yes >= 218) {
                    x.impStage = 2; x.impeachments++; x.impWeek = g.week + 3 + r.nextInt(3);
                    g.log(NK_BIG, "THE HOUSE IMPEACHES PRESIDENT " + g.pres.last.toUpperCase() + ", " + yes + "-" + (435 - yes), "The articles go to the Senate for trial.", 5);
                    if (pr < 14) { g.perf += 0.8; for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 6); } else g.perf -= 2;
                } else { x.impStage = 0; x.impResult = "The House voted down impeachment, " + yes + "-" + (435 - yes) + "."; g.log(NK_BIG, "THE HOUSE REJECTS IMPEACHMENT, " + yes + "-" + (435 - yes), null, 4); g.perf += 1; clearImpeachable(g, 0.6); }
                return;
            }
            if (x.impStage == 2 && g.week >= x.impWeek) {
                int yes = 0;
                for (Bloc b : g.cong.blocs) {
                    if (b.chamber != SENATE) continue;
                    double p = b.party == g.party ? logistic(-4.2 + 0.16 * pr + (40 - g.approval) * 0.06) : logistic(0.2 + 0.2 * pr - (b.name.contains("oderate") ? 0.4 : 0));
                    for (int i = 0; i < b.seats; i++) if (r.nextDouble() < p) yes++;
                }
                if (yes >= 67) {
                    x.impStage = 4;
                    x.impResult = "The Senate voted " + yes + "-" + (100 - yes) + " to convict. " + (g.vp != null ? g.vp.name() + " is sworn in as president." : "");
                    g.log(NK_BIG, "THE SENATE CONVICTS PRESIDENT " + g.pres.last.toUpperCase() + ", " + yes + "-" + (100 - yes), x.impResult, 6);
                    g.over = true; g.removed = true;
                } else {
                    x.impStage = 3;
                    x.impResult = "The Senate acquitted you, " + yes + " guilty to " + (100 - yes) + " not guilty; 67 votes were needed to convict.";
                    g.log(NK_BIG, "SENATE ACQUITS PRESIDENT " + g.pres.last.toUpperCase(), x.impResult, 5);
                    g.perf += pr < 14 ? 1.2 : 0;
                    clearImpeachable(g, 0.5);
                    Decisions.info(g, "Acquitted", x.impResult + " The trial is over, but the votes will be remembered.");
                }
            }
        }

        static void clearImpeachable(Game g, double k) { for (Scandal s : g.ex.scandals) if (!s.over && s.impeachable) s.severity *= k; g.ex.contempt = 0; g.ex.defiance = 0; }

        public static void impeachDecision(Game g, int k) {
            Exec x = g.ex;
            if (k == 0) { for (Scandal s : x.scandals) if (!s.over && s.impeachable) s.severity *= g.rng.nextDouble() < 0.5 ? 0.85 : 1.1; }
            else if (k == 1) { x.contempt++; for (Bloc b : g.cong.blocs) if (b.party == g.party) b.rel = Math.min(100, b.rel + 3); }
            else { g.stamina = Math.max(0, g.stamina - 10); g.perf += g.approval >= 44 ? 0.8 : -0.4; }
        }
    }

    /** The vice president's missions: tours, task forces, the Senate, fundraising and trips abroad. */
    static final class VicePres {
        public static void start(Game g, int mission, int arg) {
            Exec x = g.ex;
            x.vpMission = mission; x.vpArg = arg; x.vpUntil = VM_WEEKS[mission] > 0 ? g.week + VM_WEEKS[mission] : -1;
            if (mission != VM_NONE) { x.vpMissions++; g.log(NK_INFO, "Vice President " + g.vp.last + (mission == VM_TASK ? " will lead the administration's work on " + PISSUE[arg].toLowerCase() : mission == VM_TOUR ? " heads out on a swing-state tour" : mission == VM_MONEY ? " hits the fundraising circuit" : mission == VM_ABROAD ? " leaves on a trip to reassure allies" : " takes charge of the White House's Senate operation"), null, 0.8); }
        }

        static void week(Game g) {
            Exec x = g.ex;
            Cand v = g.vp;
            if (v == null) return;
            Random r = g.rng;
            double k = (v.a[A_CHA] + v.a[A_EST]) / 140.0;
            switch (x.vpMission) {
                case VM_TOUR: { String[] sw = {"PA", "MI", "WI", "AZ", "GA", "NC", "NV"}; int s = stateIdx(sw[g.week % sw.length]); if (s >= 0) g.stateBump[s] += 1.2 * k; g.perf += 0.01; break; }
                case VM_TASK: if (x.vpArg >= 0) { g.issueAdj[x.vpArg] = clamp(g.issueAdj[x.vpArg] + 0.015 * k, -1.5, 1.5); g.command[x.vpArg] = Math.min(100, g.command[x.vpArg] + 0.6); } break;
                case VM_SENATE: for (Bloc b : g.cong.blocs) if (b.chamber == SENATE) b.rel = Math.min(100, b.rel + 0.25 * k); break;
                case VM_MONEY: g.funds += 1.2 * v.a[A_BIG] / 70; break;
                case VM_ABROAD: g.issueAdj[PI_FOREIGN] = clamp(g.issueAdj[PI_FOREIGN] + 0.012 * k, -1.5, 1.5); break;
                default: break;
            }
            if (x.vpMission != VM_NONE && r.nextDouble() < (100 - v.a[A_DIS]) / 2600.0) {
                g.log(NK_BAD, "Vice President " + v.last + "'s off-the-cuff remarks make headlines", "The White House says the vice president was making a broader point.", 1.0);
                g.perf -= 0.25;
            }
            // a vice president with nothing to do grows restless
            x.vpLoyalty = clamp(x.vpLoyalty + (x.vpMission == VM_NONE ? -0.15 : 0.1) + (g.approval - 45) * 0.01, 0, 100);
            if (x.vpUntil >= 0 && g.week >= x.vpUntil) { g.log(NK_INFO, "Vice President " + v.last + " wraps up: " + VM_NAME[x.vpMission].toLowerCase(), null, 0.4); x.vpMission = VM_NONE; x.vpUntil = -1; }
        }
    }

    // ---------------------------------------------------------------------
    //  VicePresData (resolutedesk.executive.VicePresData): Missions a president can give the vice president.
    // ---------------------------------------------------------------------
    // ---- the vice president ----
    public static final int VM_NONE = 0, VM_TOUR = 1, VM_TASK = 2, VM_SENATE = 3, VM_MONEY = 4, VM_ABROAD = 5, NVM = 6;

    public static final String[] VM_NAME = {"Stay in Washington", "Tour the swing states", "Lead a task force", "Work the Senate", "Raise money for the party", "Represent you abroad"};

    public static final String[] VM_DESC = {"Sits in on meetings and stands by to break ties in the Senate.", "Six weeks of rallies and town halls in the battleground states.",
            "Eight weeks leading the administration's work on one issue.", "Lobbies senators personally. Improves your relationships in the Senate.",
            "Six weeks of fundraisers for the party's candidates.", "Four weeks of foreign trips to reassure allies."};

    public static final int[] VM_WEEKS = {0, 6, 8, 0, 6, 4};

    // ---------------------------------------------------------------------
    //  EraRules (resolutedesk.history.EraRules): Applying an era: the calendar, electoral votes, prices and the issues of the day.
    // ---------------------------------------------------------------------
    /** The year in which the game's current term began. */
    public static int termYear(Game g) { return g.era.year + 4 * (g.term - 1); }

    /** The week the current term ends: noon on January 20 four years after it began. */
    public static int termEnd(Game g) { return (int) Math.floor(dayOfDate(termYear(g) + 4, 0, 20) / 7.0); }

    /** The calendar year now. */
    public static int yearNow(Game g) { return dateOf(g.day())[0]; }

    // ---- what changes with the era: the calendar, the Electoral College, the names of issues, the money ----------
    public static double COST_SCALE = 1;

    public static final String[] PISSUE0 = PISSUE.clone(), PISSUE_SHORT0 = PISSUE_SHORT.clone();

    public static void applyEra(Era e) {
        CAL_Y = e.year; CAL_M = e.inM; CAL_D = e.inD;
        if (STATE_EV24[0] == 0) for (int s = 0; s < NS; s++) STATE_EV24[s] = STATES[s].ev;
        setEv(e.year);
        for (int i = 0; i < NPI; i++) { PISSUE[i] = PISSUE0[i]; PISSUE_SHORT[i] = PISSUE_SHORT0[i]; }
        if (e.labels != null) for (String p : e.labels.split(" (?=\\d+=)")) {
            int k = p.indexOf('=');
            int i = Integer.parseInt(p.substring(0, k));
            PISSUE[i] = p.substring(k + 1);
            PISSUE_SHORT[i] = PISSUE[i].length() > 12 ? PISSUE[i].substring(0, PISSUE[i].indexOf(' ') > 0 ? PISSUE[i].indexOf(' ') : 12) : PISSUE[i];
        }
        COST_SCALE = e.year < 2021 ? e.nominalGdp / 29.7 : 1;
        GEN_YEAR = e.year;
        applyYear(e.year);
    }

    /** Sets the electoral votes in use for the election held in a year. */
    public static void setEv(int year) {
        if (STATE_EV24[0] == 0) for (int s = 0; s < NS; s++) STATE_EV24[s] = STATES[s].ev;
        int[] ev = evFor(year);
        for (int s = 0; s < NS; s++) STATES[s].ev = ev[s];
        EV_YEAR = year;
    }

    /** Party money ($ millions in today's terms) in the era's own dollars, in words. */
    public static String partyMoney(double m) {
        double a = Math.abs(m) * 1e6 * COST_SCALE;
        String s = a >= 9.95e6 ? "$" + Math.round(a / 1e6) + " million" : a >= 1e6 ? "$" + fmt1(a / 1e6) + " million" : a >= 1e4 ? "$" + thousands(Math.round(a / 1000) * 1000) : "$" + thousands(Math.round(a / 100) * 100);
        return (m < 0 ? "-" : "") + s;
    }

    /** The calendar year the game last changed over to (applyYear). */
    public static int CAL_YEAR = 2025;

    /** What changes with the calendar year: the press corps and the name of the president's megaphone. */
    public static void applyYear(int year) {
        eraPosts(year);
        eraChairs(year);
        CAL_YEAR = year; Flag.year = year; Flag.roc = year < 1950;
        String[] t = year < 1953 ? PRESS_1933 : year < 1981 ? PRESS_1953 : year < 1997 ? PRESS_1981 : year < 2009 ? PRESS_1997 : null;
        for (int i = 0; i < OUT_NAME.length; i++) {
            if (t == null) { OUT_NAME[i] = OUT_NAME0[i]; OUT_LEAN[i] = OUT_LEAN0[i]; OUT_AUD[i] = OUT_AUD0[i]; OUT_SIT[i] = OUT_SIT0[i]; continue; }
            String[] p = t[i].split("\\|");
            OUT_NAME[i] = p[0]; OUT_LEAN[i] = Double.parseDouble(p[1]); OUT_AUD[i] = Double.parseDouble(p[2]); OUT_SIT[i] = p[3].equals("y");
        }
        if (year >= 1971 && year < 1981) OUT_NAME[13] = "NPR";
        if (year >= 1968 && year < 1981) OUT_NAME[17] = "60 Minutes";
        if (year >= 1988 && year < 1997) OUT_NAME[12] = "Conservative talk radio";
        else if (year < 1988 && year >= 1981) { OUT_NAME[12] = "The Moral Majority Report"; OUT_AUD[12] = 1; }
        PressRoom.TABS[2] = year < 2009 ? "Statements" : "Social media";
    }

    /** History as it unfolds: the turning points of each era, the wars of the day and the world changing on schedule. */
    static final class History {
        public static void setup(Game g) {
            World w = g.world;
            w.wars = new ArrayList<War>();
            for (int i = 0; i < WAR_ID.length; i++) w.wars.add(newWar(i));
            w.hfired = new boolean[FLASH.length];
            int y = g.era.year;
            for (String s : WAR_START) {
                if (!s.startsWith(y + "|")) continue;
                for (String tok : s.substring(5).split(" ")) {
                    String[] t = tok.split(":");
                    War war = war(w, t[0]);
                    war.stage = 2; war.front = Double.parseDouble(t[1]); war.troops = Double.parseDouble(t[2]); war.support = Double.parseDouble(t[3]); war.talks = Double.parseDouble(t[4]);
                    war.started = -52;
                    if (war.stakes >= 3) war.strategy = 2;
                }
            }
            if (g.set.scenario == 2 && y < 2021 && activeWars(w) == 0) {
                War war = war(w, y < 1960 ? "korea" : y < 1990 ? "vietnam" : y < 2008 ? "afghan" : "isis");
                war.stage = 2; war.troops = war.need * 0.6; war.front = 50; war.started = 0;
            }
            g.econ.war = warSpend(w); g.econ.war0 = g.econ.war;
            // the flashpoints of years already past are spent
            for (int i = 0; i < FLASH.length; i++) if (flashDay(i) < 0) w.hfired[i] = true;
            Home h = g.home;
            if (h != null && y < 2025) {
                int[] yy = {1933, 1941, 1953, 1961, 1965, 1969, 1973, 1977, 1981, 1985, 1989, 1993, 1997, 2001, 2005, 2009, 2013, 2017, 2021};
                double[] cr = {85, 60, 55, 45, 54, 89, 112, 128, 160, 150, 179, 200, 165, 136, 126, 116, 99, 103, 107};
                double[] od = {15, 15, 15, 15, 18, 22, 25, 25, 25, 28, 30, 30, 30, 32, 38, 45, 52, 78, 100};
                for (int i = 0; i < yy.length; i++) if (y >= yy[i]) { h.crime = cr[i]; h.od = od[i]; }
                h.grid = y < 1990 ? 30 : 40;
                if (y >= 1965 && y < 1973) h.protest = 55;
                if (y == 2021) { h.pand = 2; h.pandWeek = -45; h.deaths = 400000; }
                if (y < 2009) h.followers = 0;
            }
        }

        static War newWar(int i) {
            War war = new War();
            war.id = WAR_ID[i]; war.name = WAR_NAME[i];
            String[] t = WAR_SPEC[i].split("\\|");
            war.enemy = t[0].equals("-") ? -1 : ctIdx(t[0]); war.ally = t[1].equals("-") ? -1 : ctIdx(t[1]);
            war.need = Double.parseDouble(t[2]); war.drift = Double.parseDouble(t[3]); war.lethal = Double.parseDouble(t[4]); war.cost = Double.parseDouble(t[5]);
            war.support = Double.parseDouble(t[6]); war.stakes = Double.parseDouble(t[7]);
            return war;
        }

        public static War war(World w, String id) { if (w.wars == null) return null; for (War x : w.wars) if (x.id.equals(id)) return x; return null; }

        static int activeWars(World w) { int n = 0; if (w.wars != null) for (War x : w.wars) if (x.stage == 2) n++; return n; }

        static double warSpend(World w) { double s = 0; if (w.wars != null) for (War x : w.wars) if (x.stage == 2) s += x.troops * x.cost; return s; }

        /** The game day of a flashpoint's date. */
        public static int dayOf(String f) {
            String d = f.substring(0, 10);
            return dayOfDate(Integer.parseInt(d.substring(0, 4)), Integer.parseInt(d.substring(5, 7)) - 1, Integer.parseInt(d.substring(8, 10)));
        }

        static int[] flashDays;
        static int flashKey = -1;

        /** Flashpoint days for the current calendar, cached. */
        static int flashDay(int i) {
            int key = CAL_Y * 10000 + CAL_M * 100 + CAL_D;
            if (flashDays == null || flashKey != key) {
                flashDays = new int[FLASH.length];
                for (int k = 0; k < FLASH.length; k++) flashDays[k] = dayOf(FLASH[k]);
                flashKey = key;
            }
            return flashDays[i];
        }

        /** The world of an inauguration year: names, leaders, alignments, relations, power, the bomb, trade. */
        public static void world(Game g, int year, boolean fresh) {
            World w = g.world;
            if (w.name == null) {
                w.name = new String[NC]; w.align = new int[NC]; w.base = new double[NC]; w.power = new double[NC]; w.nuke = new boolean[NC]; w.gone = new boolean[NC];
                for (int c = 0; c < NC; c++) { w.name[c] = CT_NAME[c]; w.align[c] = CT_ALIGN[c]; w.base[c] = CT_REL[c]; w.power[c] = CT_POWER[c]; w.nuke[c] = CT_NUKE[c]; }
            }
            w.modern = year >= 2009;
            w.tradeK = year >= 2021 ? 1 : g.era.nominalGdp / 29.7 * (year < 1946 ? 0.5 : year < 1971 ? 0.65 : year < 1991 ? 0.85 : 1);
            String spec = null;
            for (String s : WORLD_ERA) if (s.startsWith(year + "|")) spec = s;
            if (spec == null) return;
            for (int c = 0; c < NC; c++) {
                if (fresh) { w.name[c] = CT_NAME[c]; w.leader[c] = LEADER25[c].split("\\|")[1] + " of " + CT_NAME[c]; w.ltitle[c] = LEADER25[c].split("\\|")[1]; }
                w.gone[c] = false;
            }
            for (String b : BORN.split(" ")) { String[] p = b.split(":"); int c = ctIdx(p[0]); if (c >= 0 && year < Integer.parseInt(p[1])) w.gone[c] = true; }
            for (String b : NUKES.split(" ")) { String[] p = b.split(":"); int c = ctIdx(p[0]); if (c >= 0) w.nuke[c] = year >= Integer.parseInt(p[1]); }
            if (year < 1947) for (int c = 0; c < NC; c++) if (w.align[c] == AL_TREATY) w.align[c] = AL_PARTNER;
            for (String tok : spec.substring(5).split("\\^")) {
                int eq = tok.indexOf('=');
                int c = ctIdx(tok.substring(0, eq));
                if (c < 0) continue;
                String v = tok.substring(eq + 1);
                if (v.equals("-")) { w.gone[c] = true; continue; }
                w.gone[c] = false;
                String[] p = v.split(";", -1);
                if (!p[0].isEmpty()) w.name[c] = p[0]; else if (fresh) w.name[c] = CT_NAME[c];
                if (!p[1].isEmpty()) { w.leader[c] = p[1]; w.ltitle[c] = p[2]; }
                if (!p[3].isEmpty()) { double nb = Double.parseDouble(p[3]); if (fresh) w.rel[c] = nb; else w.rel[c] = clamp(w.rel[c] + (nb - w.base[c]) * 0.5, -100, 100); w.base[c] = nb; }
                if (!p[4].isEmpty()) w.align[c] = Integer.parseInt(p[4]);
                if (p.length > 5 && !p[5].isEmpty()) w.power[c] = Double.parseDouble(p[5]);
            }
            if (!w.modern) {
                w.twStage = 0; w.twt = 10; w.uaStage = 0; w.ukr = 50; w.talks = 0; w.gaza = 10; w.iran = 5; w.redsea = 5; w.proxy = 10; w.nk = year >= 1953 ? 40 : 0;
                w.terror = year >= 1993 ? 35 : 10; w.cyber = year >= 1995 ? 25 : 0; w.migr = year >= 1975 ? 40 : 20; w.cartel = year >= 1980 ? 40 : 10;
                for (int c = 0; c < NC; c++) { w.sanction[c] = 0; w.aid[c] = 0; }
                if (year >= 1960 && year < 2015) w.sanction[CC_CU] = 3;
                if (year >= 1950) w.sanction[CC_KP] = 3;
                if (year >= 1950 && year < 1972) w.sanction[CC_CN] = 3;
                if (year >= 1979) w.sanction[CC_IR] = 2;
                if (year >= 1990 && year < 2003) w.sanction[CC_IQ] = 3;
                if (year >= 1948 && year < 1991) w.sanction[CC_RU] = 1;
                if (year >= 1945) w.aid[CC_IL] = year >= 1973 ? 2 : 0;
                if (year >= 1979) w.aid[CC_EG] = 1;
                if (year >= 1955 && year < 1975) w.aid[CC_VN] = 2;
                w.nato = year >= 1949 ? 60 : 30; w.pacific = year >= 1952 ? 60 : 30; w.allySpend = year < 1991 ? 3.5 : 1.8;
            } else if (year < 2025) {
                w.twStage = year >= 2021 ? 1 : 0; w.twt = year >= 2021 ? 40 : 30;
                w.uaStage = year >= 2017 ? 1 : 0; w.ukr = 50; w.talks = year >= 2017 ? 30 : 0;
                w.gaza = 25; w.iran = year >= 2017 ? 45 : 60; w.redsea = 20; w.proxy = year >= 2013 ? 45 : 35; w.nk = year >= 2017 ? 70 : 55; w.terror = 45;
                w.aid[CC_UA] = year >= 2017 ? 1 : 0;
            }
            for (int c = 0; c < NC; c++) if (w.gone[c]) { w.tariff[c] = 0; w.sanction[c] = 0; w.aid[c] = 0; }
        }

        public static void week(Game g) {
            World w = g.world;
            if (w.wars == null) return;
            // a new era's leaders arrive on inauguration day, four years on
            int y = yearNow(g);
            int[] d = dateOf(g.day());
            if (d[1] == 0 && d[2] >= 14 && d[2] <= 27 && y % 4 == 1 && y != g.era.year && y < 2025 && w.worldYear != y) { w.worldYear = y; world(g, y, false); }
            if (d[1] == 0 && d[2] <= 7 && w.pressYear != y) {
                boolean[] was = new boolean[NPOST];
                for (int k = 0; k < NPOST; k++) was[k] = POST_OFF[k];
                w.pressYear = y; applyYear(y); GEN_YEAR = y;
                for (int k = 0; k < NPOST; k++) if (was[k] && !POST_OFF[k]) Cabinet.created(g, k);
                // committees renamed by Congress keep their chairs
                for (Member m : g.cong.members) if (m.role == RO_CHAIR) {
                    String[] names = m.chamber == HOUSE ? CHAIR_H : CHAIR_S;
                    for (int k = 0; k < names.length; k++) if (sameCommittee(m.chamber, k, m.committee)) { m.committee = names[k]; m.title = "Chair, " + (m.chamber == HOUSE ? "House " : "Senate ") + names[k]; break; }
                }
            }
            wars(g);
            flash(g);
        }

        static void wars(Game g) {
            World w = g.world;
            Random r = g.rng;
            double dq = Cabinet.pq(g, P_DEF);
            for (War x : w.wars) {
                if (x.stage != 2) continue;
                x.weeks++;
                double eff = x.troops <= 0 ? -1.2 : clamp(Math.log(x.troops / x.need) * 0.9, -1.5, 1.2);
                double strat = x.strategy == 0 ? -0.15 : x.strategy == 2 ? 0.45 : x.strategy == 3 ? -0.2 : 0;
                double allyK = x.ally >= 0 ? (w.rel[x.ally] - 40) * 0.003 : 0;
                double sk = Math.sqrt(Math.max(0.5, x.stakes));
                x.front = clamp(x.front + (x.drift + eff * 0.35 + strat + allyK + (dq - 0.6) * 0.4 + r.nextGaussian() * 0.9) / sk, 0, 100);
                double kiaRate = x.lethal * (x.strategy == 0 ? 0.6 : x.strategy == 2 ? 1.6 : x.strategy == 3 ? 0.7 : 1) * (1.2 - dq * 0.4);
                double dead = x.troops * kiaRate * (0.6 + 0.8 * r.nextDouble());
                x.kia += dead;
                w.kia += (int) Math.round(dead);
                if (dead > 0) g.perf -= Math.min(0.4, dead / (x.stakes * x.stakes) / 3000.0);
                double supT = 35 + 18 * Math.min(3, x.stakes);
                x.support = clamp(x.support + (supT - x.support) * 0.01 - dead / x.stakes / 2000.0 - (x.weeks > 104 ? 0.03 : 0) + (x.front - 50) * 0.003, 5, 98);
                x.talks = clamp(x.talks + (x.strategy == 3 ? 1.5 : 0.1) + (x.front > 65 ? 0.4 : 0) - (x.front < 35 ? 0.3 : 0) + r.nextGaussian() * 0.6, 0, 100);
                g.issueAdj[PI_SECURITY] = clamp(g.issueAdj[PI_SECURITY] + (x.support - 50) * 0.0004 + (x.front - 50) * 0.0002, -1.5, 1.5);
                g.issueSal[PI_SECURITY] = clamp(g.issueSal[PI_SECURITY] + 0.004 * x.stakes, 0.2, 2.2);
                if (dead > 50 && r.nextDouble() < 0.06) g.log(NK_WORLD, x.name + ": " + thousands(Math.round(x.kia)) + " Americans killed so far", null, 1.2);
                if (x.front >= 100) end(g, x, 3);
                else if (x.front <= 0) end(g, x, 4);
                else if (x.talks >= 100 && x.front >= 25) end(g, x, 5);
                else if (x.troops <= 0.5 && x.weeks > 4) end(g, x, x.front >= 60 ? 5 : 4);
            }
            g.econ.war = warSpend(w);
        }

        static void end(Game g, War x, int how) {
            if (x.stage != 2) return;
            x.stage = how; x.ended = g.week;
            String title = how == 3 ? x.name.toUpperCase() + " ENDS IN VICTORY" : how == 4 ? x.name.toUpperCase() + " ENDS IN DEFEAT" : x.name.toUpperCase() + " ENDS IN AN AGREEMENT";
            String body = thousands(Math.round(x.kia)) + " Americans died over " + Math.round(x.weeks / 52.0 * 10) / 10.0 + " years.";
            g.log(NK_BIG, title, body, 5);
            String nm = x.name.startsWith("The ") ? "the " + x.name.substring(4) : x.name;
            String when = dateStr(g.day()) + ": ";
            g.world.record.add(when + nm + (how == 3 ? " won" : how == 4 ? " lost" : " ended by agreement"));
            if (how == 3) { g.perf += 3 + x.stakes; g.rally += 6 + x.stakes * 2; g.issueAdj[PI_SECURITY] = clamp(g.issueAdj[PI_SECURITY] + 0.5, -1.5, 1.5); g.milestones.add(when + "won " + nm); }
            else if (how == 4) { g.perf -= 3; g.issueAdj[PI_FOREIGN] = clamp(g.issueAdj[PI_FOREIGN] - 0.5, -1.5, 1.5); g.milestones.add(when + "lost " + nm); }
            else { g.perf += 1.5; g.milestones.add(when + "ended " + nm + " by agreement"); }
            if (x.id.equals("ww2e") && how == 3 && x.enemy >= 0) { g.world.rel[x.enemy] = 0; g.world.align[x.enemy] = 0; g.world.leader[x.enemy] = "the Allied occupation"; g.world.ltitle[x.enemy] = "Military government"; }
            if (x.id.equals("ww2p") && how == 3 && x.enemy >= 0) { g.world.rel[x.enemy] = 10; g.world.align[x.enemy] = 0; g.world.leader[x.enemy] = "the American occupation"; g.world.ltitle[x.enemy] = "Military government"; }
            if (how == 3 && x.stakes >= 3) g.econ.demandShock += 0.45 * x.troops * x.cost * 0.8;
            x.troops = 0;
            Decisions.info(g, how == 3 ? "Victory" : how == 4 ? "Defeat" : "The War Is Over", x.name + (how == 3 ? " ends in victory. " : how == 4 ? " ends in defeat. " : " ends in an agreement. ") + body);
        }

        static void flash(Game g) {
            World w = g.world;
            int today = g.day();
            for (int i = 0; i < FLASH.length; i++) {
                if (w.hfired[i]) continue;
                String[] t = FLASH[i].split("\\|", 7);
                int day = flashDay(i), win = Integer.parseInt(t[1]);
                if (today + 7 <= day) continue;
                if (today > day + win * 7) { w.hfired[i] = true; continue; }
                if (!cond(g, t[2])) continue;
                w.hfired[i] = true;
                if (!t[5].isEmpty()) Diplo.fx(g, t[5]);
                g.log(NK_BIG, t[3].toUpperCase(), null, 3.5);
                if (t[6].isEmpty()) { Decisions.info(g, t[3], t[4]); return; }
                String[] opts = t[6].split(";;");
                String[] lab = new String[opts.length], adv = new String[opts.length];
                for (int k = 0; k < opts.length; k++) {
                    String[] o = opts[k].split("\\|");
                    lab[k] = o[0];
                    adv[k] = o[1] + ": \"" + Diplo.odds(g, o[2], Double.parseDouble(o[3])) + "\"";
                }
                Decision dd = Decisions.add(g, D_HIST, t[3], t[4] + " Your advisers each have a view; the odds are their best guess.", lab, adv);
                dd.a = i;
                g.stress = Math.min(100, g.stress + 4);
                return;
            }
        }

        public static void decide(Game g, int i, int k) {
            String[] t = FLASH[i].split("\\|", 7);
            String[] o = t[6].split(";;")[k].split("\\|");
            boolean ok = g.rng.nextDouble() < Diplo.p(g, o[2], Double.parseDouble(o[3]));
            Diplo.fx(g, ok ? o[4] : o[5]);
            if (ok) { g.okCount++; g.histOk.add(t[3] + ": " + o[0]); } else g.failCount++;
            String story = ok ? o[6] : o[7];
            g.log(ok ? NK_GOOD : NK_BAD, story, null, 2.2);
            g.milestones.add(dateStr(g.day()) + ": " + t[3] + " - " + o[0].toLowerCase());
            Decisions.info(g, ok ? "It worked" : "It didn't go as hoped", story);
        }

        public static int auto(Game g, int i) {
            String[] o = FLASH[i].split("\\|", 7)[6].split(";;");
            int best = 0;
            double bv = -9;
            for (int k = 0; k < o.length; k++) {
                String[] t = o[k].split("\\|");
                double q = Diplo.p(g, t[2], Double.parseDouble(t[3]));
                double v = q + (t[4].contains("perf=-") ? -0.15 : 0) + (t[4].contains("rights=-") ? -0.3 : 0) - (q >= 1 ? 0.25 : 0);
                if (v > bv) { bv = v; best = k; }
            }
            return best;
        }

        static double var(Game g, String k) {
            World w = g.world;
            if (k.equals("year")) return yearNow(g);
            if (k.startsWith("war_")) { War x = war(w, k.substring(4)); return x == null ? 0 : x.stage; }
            if (k.startsWith("front_")) { War x = war(w, k.substring(6)); return x == null ? 0 : x.front; }
            if (k.startsWith("troops_")) { War x = war(w, k.substring(7)); return x == null ? 0 : x.troops; }
            if (k.startsWith("rel_")) { int c = ctIdx(k.substring(4)); return c < 0 ? 0 : w.rel[c]; }
            return HomeFront.var(g, k);
        }

        static boolean cond(Game g, String c) {
            if (c.isEmpty()) return true;
            for (String t : c.split(",")) {
                if (t.startsWith("p=")) { if (g.rng.nextDouble() >= Double.parseDouble(t.substring(2))) return false; continue; }
                int i = t.indexOf('>'), j = t.indexOf('<');
                if (i > 0) { if (!(var(g, t.substring(0, i)) > Double.parseDouble(t.substring(i + 1)))) return false; }
                else if (j > 0) { if (!(var(g, t.substring(0, j)) < Double.parseDouble(t.substring(j + 1)))) return false; }
            }
            return true;
        }

        /** The effects history adds to the interpreter: wars, leaders, alignments. Returns true if it handled the key. */
        public static boolean fxKey(Game g, String k, String v) {
            World w = g.world;
            int c2 = k.indexOf(':');
            if (c2 < 0) {
                if (k.equals("pandnow")) { if (g.home != null && g.home.pand == 0) { g.home.pand = 2; g.home.pandWeek = g.week; } return true; }
                if (k.equals("slump")) { g.econ.slump += Double.parseDouble(v); return true; }
                return false;
            }
            String key = k.substring(0, c2), arg = k.substring(c2 + 1);
            War x = war(w, arg);
            if (key.equals("warstart")) { if (x != null && x.stage != 2) { x.stage = 2; g.warsStarted++; x.troops = Double.parseDouble(v); x.front = 50; x.started = g.week; x.weeks = 0; g.rally += 4 + x.stakes; g.log(NK_BIG, ("America goes to war: " + x.name).toUpperCase(), null, 5); g.econ.war = warSpend(w); } return true; }
            if (key.equals("war")) { if (x != null && x.stage == 2) x.front = clamp(x.front + Double.parseDouble(v), 0, 100); return true; }
            if (key.equals("troops")) { if (x != null && x.stage == 2) x.troops = Math.max(0, x.troops + Double.parseDouble(v)); g.econ.war = warSpend(w); return true; }
            if (key.equals("strat")) { if (x != null && x.stage == 2) x.strategy = (int) Double.parseDouble(v); return true; }
            if (key.equals("talks")) { if (x != null && x.stage == 2) x.talks = clamp(x.talks + Double.parseDouble(v), 0, 100); return true; }
            if (key.equals("support")) { if (x != null && x.stage == 2) x.support = clamp(x.support + Double.parseDouble(v), 0, 100); return true; }
            if (key.equals("warend")) { if (x != null && x.stage == 2) end(g, x, (int) Double.parseDouble(v)); return true; }
            int c = ctIdx(arg);
            if (key.equals("leader")) { if (c == CC_CN) Flag.roc = false; if (c >= 0) { String[] p = v.split(";"); w.leader[c] = p[0].replace('_', ' '); w.ltitle[c] = p.length > 1 ? p[1].replace('_', ' ') : w.ltitle[c]; } return true; }
            if (key.equals("align")) { if (c >= 0 && w.align != null) w.align[c] = (int) Double.parseDouble(v); return true; }
            if (key.equals("name")) { if (c >= 0 && w.name != null) w.name[c] = v.replace('_', ' '); return true; }
            if (key.equals("nuke")) { if (c >= 0 && w.nuke != null) w.nuke[c] = Double.parseDouble(v) > 0; return true; }
            if (key.equals("gone")) { if (c >= 0 && w.gone != null) w.gone[c] = Double.parseDouble(v) > 0; return true; }
            if (key.equals("power")) { if (c >= 0 && w.power != null) w.power[c] = Double.parseDouble(v); return true; }
            if (key.equals("aid")) { if (c >= 0) w.aid[c] = (int) Double.parseDouble(v); return true; }
            return false;
        }

        // ---- the president's levers in a war ----
        public static void setTroops(Game g, War x, double t) {
            if (x.stage != 2) return;
            double old = x.troops;
            x.troops = clamp(t, 0, x.need * 1.6);
            g.econ.war = warSpend(g.world);
            if (x.troops > old) { x.support = clamp(x.support - 2 / x.stakes, 0, 100); g.log(NK_WORLD, "The president orders " + thousands(Math.round((x.troops - old) * 1000)) + " more troops to " + x.name.toLowerCase().replace("the ", ""), null, 1.6); }
            else if (x.troops < old) g.log(NK_WORLD, thousands(Math.round((old - x.troops) * 1000)) + " troops are coming home from " + x.name.toLowerCase().replace("the ", ""), null, 1.6);
        }

        public static void setStrategy(Game g, War x, int s) {
            if (x.stage != 2 || x.strategy == s) return;
            x.strategy = s;
            g.log(NK_WORLD, x.name + ": the president orders a new strategy, " + STRATEGY[s].toLowerCase(), null, 1.0);
        }

        public static void withdraw(Game g, War x) {
            if (x.stage != 2) return;
            end(g, x, x.front >= 60 ? 5 : 4);
        }

        /** What a hands-off president does with a war: send what the generals ask while the public backs it, look for a way out when it doesn't. */
        public static void autoWar(Game g) {
            if (g.world == null || g.world.wars == null || g.week % 4 != 0) return;
            for (War x : g.world.wars) {
                if (x.stage != 2) continue;
                double target = x.support < 30 ? x.troops * 0.85 : x.front < 85 ? x.need * 1.25 : x.need;
                if (x.stakes >= 3) target = x.need * 1.4;
                setTroops(g, x, x.troops + (target - x.troops) * 0.25);
                int s = x.support < 35 && x.stakes < 2 ? 3 : x.front < 40 && x.support > 50 ? 2 : 1;
                if (x.stakes >= 3 && x.front < 90) s = 2;
                setStrategy(g, x, s);
            }
        }

        public static String countryName(Game g, int c) { return g.world != null && g.world.name != null ? g.world.name[c] : CT_NAME[c]; }
    }

    // ---------------------------------------------------------------------
    //  HistoryData (resolutedesk.history.HistoryData): Turning points of history and the world of each era.
    // ---------------------------------------------------------------------
    /** The world on each inauguration day: "year|CC=name;leader;title;rel;align;power^...", blank fields keep today's value, "CC=-" means not a country then. */
